/**
 * Tests of the lazy validator of T232 (F100-FR-048, F100-FR-049):
 * `validatorFor(schemaId)` is keyed by the value a record carries in its
 * `schema` field, reads the schema file of the id through the package's
 * own file map (`src/records/schema-map.ts`, generated by
 * `scripts/types.mjs`), compiles it at first use, and caches it;
 * `validate(schemaId, value)` returns the typed record or the list of
 * errors, and refuses a record whose major differs from the one the
 * schema supports.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import {
  validate,
  validatorFor,
  UnknownSchemaError,
  UnsupportedMajorError,
} from "../src/records/compile.ts";

/** A valid lease record of major 1 (annex B, §B.8). */
function leaseRecord(): Record<string, unknown> {
  return {
    schema: "specstride.lease/1",
    runId: "run:1",
    launchId: "launch:1",
    launchNonce: "nonce",
    owner: {
      pid: 1,
      processGroup: 1,
      startTime: 0,
      bootId: "boot",
      hostName: "host",
      pidNamespace: "ns",
      launchId: "launch:1",
      runTokenHash: "hash",
    },
    lockProvider: "provider",
    heartbeatAt: "2026-09-30T12:00:00Z",
    heartbeatEverySeconds: 30,
    validUntil: "2026-09-30T12:05:00Z",
    leaseTokenHash: "token-hash",
  };
}

test("a valid record of the schema id it carries passes", () => {
  const result = validate(leaseRecord());
  assert.equal(result.ok, true, JSON.stringify((result as { errors?: unknown[] }).errors));
});

test("a record missing a required field fails with the list of errors", () => {
  const record = leaseRecord();
  delete record["leaseTokenHash"];
  const result = validate(record);
  assert.equal(result.ok, false);
  if (!result.ok) {
    assert.ok(result.errors.length > 0, "the refusal holds the list of errors");
  }
});

test("a record whose major differs from the one the schema supports is refused (F100-FR-049)", () => {
  const result = validate({ ...leaseRecord(), schema: "specstride.lease/2" });
  assert.equal(result.ok, false);
  if (!result.ok) {
    const major = result.errors.find((e) => e.keyword === "different-major");
    assert.ok(major !== undefined, "the refusal carries the different-major keyword");
    assert.ok(major.message.includes("2"), "the refusal names the major found");
    assert.ok(major.message.includes("1"), "the refusal names the major supported");
  }
});

test("validating against an unsupported major is refused with the majors named (F100-FR-049)", () => {
  const result = validate("specstride.lease/2", leaseRecord());
  assert.equal(result.ok, false);
  if (!result.ok) {
    assert.ok(result.errors.some((e) => e.keyword === "different-major"));
  }
  assert.throws(
    () => validatorFor("specstride.lease/2"),
    (err: unknown) =>
      err instanceof UnsupportedMajorError &&
      err.majorFound === "2" &&
      err.majorsSupported.includes("1"),
  );
});

test("an id the package does not hold is refused as unknown (F100-FR-049)", () => {
  const result = validate("specstride.nonsense/9", { schema: "specstride.nonsense/9" });
  assert.equal(result.ok, false);
  if (!result.ok) {
    assert.ok(result.errors.some((e) => e.keyword === "unknown-schema"));
  }
  assert.throws(() => validatorFor("specstride.nonsense/9"), UnknownSchemaError);
});

test("the validator of a schema id is compiled at first use and cached afterwards (F100-FR-048)", () => {
  const first = validatorFor("specstride.lease/1");
  const second = validatorFor("specstride.lease/1");
  assert.equal(first, second, "the compiled validator is cached per schema id");
  assert.notEqual(
    validatorFor("specstride.run-state/1"),
    first,
    "each schema id has its own validator",
  );
});
